SourceCode.Declaration:
/// <summary>
/// Extension of <c>CustPackingSlipJour</c> to trigger the sales packing slip posted business event.
/// </summary>
[ExtensionOf(tableStr(CustPackingSlipJour))]
final class AAXCustPackingSlipJour_Table_Extension
{
}

Method.Source:
/// <summary>
/// Triggers the sales packing slip posted business event when a packing slip journal is created.
/// </summary>
void insert()
{
    next insert();

    if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(AAXSalesPackingSlipPostedBusinessEvent)))
    {
        AAXSalesPackingSlipPostedBusinessEvent::newFromCustPackingSlipJour(this).send();
    }
}
